// Generic style-locked motion graphics. Source of truth: .agents/skills/style-motion/templates/remotion/
// (`style_motion.py install` copies it into src/). Props come from `style_motion.py render`.
//
// A scene is a stack of layers generated by Antigravity NanoBanana 2+ (plate, backdrop, hero, props), Manim Community animated plots
// (`layers.plot` as alpha-transparent WebM or MP4), plus code-drawn ornaments and type.
// Layouts: orbit | fullbleed | stack | split | plot. Formats: any canvas; geometry scales with u = min(W, H) / 1080.
import React from "react";
import {
  AbsoluteFill, Audio, Composition, Img, OffthreadVideo, Sequence, continueRender, delayRender,
  interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { ProceduralCanvas, AnimateKitName } from "./ProceduralCanvas";
import { BangMotionOverlay } from "./BangMotionOverlay";

export type Layout = "orbit" | "fullbleed" | "stack" | "split" | "plot" | "canvas" | "bang";
export type SafeInsets = {top: number; bottom: number; left: number; right: number};
export const SAFE_9X16: SafeInsets = {top: 250, bottom: 350, left: 60, right: 140};
export const SAFE_4X5: SafeInsets = {top: 120, bottom: 220, left: 60, right: 60};
export const SAFE_1X1: SafeInsets = {top: 60, bottom: 60, left: 60, right: 60};
export const SAFE_16X9: SafeInsets = {top: 60, bottom: 60, left: 60, right: 60};

const getSafeInsets = (W: number, H: number): SafeInsets => {
  if (H > W * 1.5) return SAFE_9X16;
  if (H > W * 1.1) return SAFE_4X5;
  if (W > H * 1.3) return SAFE_16X9;
  return SAFE_1X1;
};

type Scene = {
  id: number; from: number; frames: number; layout?: Layout; kicker?: string; headline: string; accent?: string[];
  caption: string; circles?: string[]; layers: Record<string, string>; plot?: Record<string, any>;
  canvas?: {kit: AnimateKitName; bpm?: number; transparent?: boolean};
  bang?: {video: string; transparent?: boolean; blendMode?: React.CSSProperties["mixBlendMode"]};
};
type TypeSpec = Record<string, any>;
export type Style = {
  canvas: {width: number; height: number; fps: number};
  palette: Record<string, string>;
  background?: {type: "radial" | "solid" | "plate"; from?: string; to?: string};
  layout?: Layout;
  ornaments?: {circles?: boolean; ring?: boolean; sparkles?: boolean; color?: string};
  motion?: {enter?: "rise" | "pop" | "fade" | "slide"; stagger?: number; damping?: number; drift?: number;
    transition?: "drift" | "fade" | "cut" | "wipe"; headline?: "word" | "line"; fade?: number};
  type: {headline: TypeSpec; caption: TypeSpec; kicker?: TypeSpec; fonts?: string[]};
};
export type StyleMotionProps = {style: Style; scenes: Scene[]; audio: string | null};

const clamp = {extrapolateLeft: "clamp", extrapolateRight: "clamp"} as const;
const col = (P: Record<string, string>, k?: string, fb = "#000") => (k ? P[k] ?? k : fb);
const isLightHex = (hex: string) => {
  const c = hex.replace("#", "");
  if (c.length !== 6) return false;
  const r = parseInt(c.slice(0, 2), 16), g = parseInt(c.slice(2, 4), 16), b = parseInt(c.slice(4, 6), 16);
  return (0.299 * r + 0.587 * g + 0.114 * b) > 185;
};
const contrastInk = (fg: string, bg: string) => (isLightHex(bg) && isLightHex(fg) ? "#141414" : fg);

const Sparkle: React.FC<{x: number; y: number; s: number; phase: number; color: string}> = ({x, y, s, phase, color}) => {
  const f = useCurrentFrame();
  const k = 0.6 + 0.5 * (0.5 + 0.5 * Math.sin(f / 9 + phase));
  return (
    <svg style={{position: "absolute", left: x - s, top: y - s, opacity: k}} width={s * 2} height={s * 2} viewBox="-10 -10 20 20">
      <path d="M0 -10 L2 -2 L10 0 L2 2 L0 10 L-2 2 L-10 0 L-2 -2 Z" fill={color} transform={`scale(${k})`} />
    </svg>
  );
};

// Layer placement per layout, in units of u around the scene anchor (cx, cy). w = width in u.
type Spot = {x: number; y: number; w: number; h?: number; drift: number; grow?: number};
const spots = (layout: Layout, portrait: boolean, nProps: number) => {
  if (layout === "plot") {
    const pw = portrait ? 820 : 1020;
    const ph = portrait ? 820 : 640;
    const py = portrait ? 30 : 20;
    const row = Array.from({length: nProps}, (_, i): Spot => ({
      x: (i - (nProps - 1) / 2) * 280, y: py + ph * 0.52, w: 200, drift: i % 2 ? 0.6 : -0.6,
    }));
    return {
      hero: {x: 0, y: py, w: pw, h: ph, drift: 0.15, grow: 0.015} as Spot,
      backdrop: {x: 0, y: py + 12, w: pw + 40, h: ph + 40, drift: -0.2} as Spot,
      props: row,
    };
  }
  if (layout === "stack") {
    const row = Array.from({length: nProps}, (_, i): Spot => ({x: (i - (nProps - 1) / 2) * 300, y: 360, w: 260, drift: i % 2 ? 1 : -1}));
    const row2 = row.map((r) => ({...r, x: r.x * 0.8, y: 290, w: 210}));
    return {hero: {x: 0, y: -40, w: 500, drift: 0.2, grow: 0.03} as Spot, backdrop: {x: 0, y: -30, w: 640, drift: -0.4} as Spot, props: row2};
  }
  if (layout === "split") {
    const hx = portrait ? 0 : 230, hy = portrait ? -140 : 0;
    return {hero: {x: hx, y: hy, w: 720, drift: 0.3, grow: 0.04} as Spot, backdrop: {x: hx + 40, y: hy + 40, w: 840, drift: -0.5} as Spot,
      props: [{x: hx - 260, y: hy + 240, w: 300, drift: -1}, {x: hx + 280, y: hy - 240, w: 300, drift: 1}] as Spot[]};
  }
  // orbit (default) and fullbleed share the centered collage geometry
  return {hero: {x: 0, y: 0, w: 820, drift: 0.3, grow: 0.04} as Spot, backdrop: {x: 40, y: 60, w: 920, drift: -0.5} as Spot,
    props: [{x: -280, y: -300, w: 420, drift: -1}, {x: 280, y: 300, w: 420, drift: 1}, {x: -300, y: 280, w: 380, drift: 1}, {x: 300, y: -280, w: 380, drift: -1}] as Spot[]};
};

const SceneView: React.FC<{sc: Scene; style: Style; fade: number}> = ({sc, style, fade}) => {
  const f = useCurrentFrame();
  const {fps, width: W, height: H} = useVideoConfig();
  const P = style.palette;
  const M = {enter: "rise", stagger: 5, damping: 18, drift: 1, transition: "drift", headline: "word", ...style.motion};
  const O = {circles: true, ring: true, sparkles: true, color: "gold", ...style.ornaments};
  const layout: Layout = sc.layout ?? style.layout ?? "orbit";
  const u = Math.min(W, H) / 1080;
  const portrait = H >= W;
  const safe = getSafeInsets(W, H);
  const safeW = W - safe.left - safe.right;
  const safeCx = safe.left + safeW / 2;
  const safeCy = safe.top + (H - safe.top - safe.bottom) / 2;
  const textLeft = layout === "split" && !portrait;
  const cx = portrait ? safeCx : W / 2;
  const cy = layout === "split" && portrait ? safeCy - 40 * u : safeCy + (portrait ? 30 * u : 0);
  const life = f / sc.frames;
  const enter = (i: number) => spring({frame: f - i * M.stagger, fps, config: {damping: M.damping, mass: 0.8}});
  const out = fade > 0 ? interpolate(f, [sc.frames - fade, sc.frames], [0, 1], clamp) : 0;
  const inn = M.transition === "cut" ? 1 : fade > 0 ? interpolate(f, [0, fade], [0, 1], clamp) : 1;
  const orn = col(P, O.color, "#C9A043");

  const enterXf = (e: number) => M.enter === "pop" ? `scale(${0.6 + 0.4 * e})`
    : M.enter === "slide" ? `translateX(${(1 - e) * -120 * u}px)`
    : M.enter === "fade" ? "" : `translateY(${(1 - e) * 40 * u}px) scale(${0.94 + 0.06 * e})`;

  const layer = (src: string | undefined, i: number, s: Spot) => {
    if (!src) return null;
    const e = enter(i), w = Math.min(s.w * u, safeW), d = s.drift * M.drift;
    return (
      <Img key={src} src={staticFile(src)} style={{
        position: "absolute", width: w, left: cx + s.x * u - w / 2, top: cy + s.y * u - w / 2, opacity: e,
        transform: `translate(${d * life * 14 * u}px, ${-d * life * 8 * u}px) ${enterXf(e)} scale(${1 + (s.grow ?? 0) * life})`,
      }} />
    );
  };

  const plotVideoLayer = (src: string | undefined, i: number, s: Spot, showCard: boolean) => {
    if (!src) return null;
    const e = enter(i);
    const w = Math.min(s.w * u, safeW);
    const h = s.h ? Math.min(s.h * u, H - safe.top - safe.bottom - 220 * u) : w;
    const d = s.drift * M.drift;
    const isTransparent = src.toLowerCase().endsWith(".webm");
    return (
      <div
        key={src}
        style={{
          position: "absolute",
          width: w,
          height: h,
          left: cx + s.x * u - w / 2,
          top: cy + s.y * u - h / 2,
          opacity: e,
          transform: `translate(${d * life * 10 * u}px, ${-d * life * 6 * u}px) ${enterXf(e)} scale(${1 + (s.grow ?? 0) * life})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {showCard && (
          <div
            style={{
              position: "absolute",
              inset: -16 * u,
              borderRadius: 20 * u,
              background: `${col(P, "paperShade", col(P, "paper"))}CC`,
              border: `2px solid ${col(P, "rule", orn)}55`,
              boxShadow: "0 16px 36px rgba(0,0,0,0.28)",
              zIndex: 0,
            }}
          />
        )}
        <OffthreadVideo
          src={staticFile(src)}
          transparent={isTransparent}
          muted
          style={{
            position: "relative",
            zIndex: 1,
            width: "100%",
            height: "100%",
            objectFit: "contain",
          }}
        />
      </div>
    );
  };

  const props = Object.keys(sc.layers).filter((k) => k.startsWith("prop")).sort();
  const g = spots(layout, portrait, props.length);
  const R = 390 * u * (g.hero.w / 920);
  const hasPlotVideo = Boolean(sc.layers.plot);
  const hasSeparateHero = Boolean(sc.layers.hero && (!sc.layers.plot_still || sc.layers.hero !== sc.layers.plot_still));

  // scene-level transition
  const wrap: React.CSSProperties = M.transition === "wipe"
    ? {clipPath: `inset(0 ${out * 100}% 0 0)`}
    : {opacity: M.transition === "cut" ? 1 : inn * (1 - out), transform: M.transition === "drift" ? `translateY(${-30 * out * u}px)` : undefined};

  // type — clamped to platform safe area (§2.1)
  const T = style.type, Hd = T.headline, C = T.caption, K = T.kicker;
  const sz = (v: number) => v * u;
  const ty = (v: number) => (v <= 1 ? v * H : v * (H / 1920));
  const words = sc.headline.split(" ");
  const accent = new Set((sc.accent ?? []).map((w) => w.toUpperCase().replace(/[^A-Z0-9]/g, "")));
  const textBox: React.CSSProperties = textLeft
    ? {position: "absolute", left: Math.max(safe.left, 110 * u), width: W * 0.42, textAlign: "left"}
    : {position: "absolute", left: safe.left, width: safeW, textAlign: "center", padding: `0 ${24 * u}px`, boxSizing: "border-box"};

  const rawKTop = textLeft ? H * 0.34 - sz(K?.size ?? 30) * 2.2 : ty(K?.y ?? 110);
  const kTop = Math.max(safe.top, rawKTop);
  const rawHeadTop = textLeft ? H * 0.34 : ty(Hd.y ?? 170);
  const headTop = Math.max(safe.top + (sc.kicker && K ? sz(K.size ?? 28) * 1.6 : 0), rawHeadTop);
  const rawCapTop = textLeft ? H * 0.34 + sz(Hd.size ?? 64) * 2.6 : ty(C.y ?? 1640);
  const capTop = Math.min(H - safe.bottom - sz(C.size ?? 34) * 2.2, rawCapTop);

  return (
    <AbsoluteFill style={wrap}>
      {layout === "fullbleed" && sc.layers.plate && (
        <>
          <Img src={staticFile(sc.layers.plate)} style={{position: "absolute", inset: 0, width: W, height: H, objectFit: "cover",
            transform: `scale(${1.02 + 0.06 * life}) translateY(${-10 * life * u}px)`}} />
          <AbsoluteFill style={{background: `linear-gradient(to bottom, ${col(P, "paper")}EE 0%, transparent 22%, transparent 70%, ${col(P, "paper")}F2 92%)`}} />
        </>
      )}
      {layout !== "fullbleed" && layout !== "plot" && O.circles && (sc.circles ?? ["green", "gold"]).map((c, i) => {
        const k = g.hero.w / 920;
        const e = enter(i), r = (i === 0 ? 310 : 115) * u * k;
        const [ox, oy] = (i === 0 ? [-40, 20] : [230, -250]).map((v) => v * u * k);
        const ax = cx + g.hero.x * u, ay = cy + g.hero.y * u;
        return <div key={i} style={{position: "absolute", left: ax + ox - r, top: ay + oy - r, width: r * 2, height: r * 2,
          borderRadius: "50%", background: col(P, c), transform: `scale(${e}) rotate(${3 * life}deg)`, opacity: 0.95}} />;
      })}
      {layout !== "fullbleed" && layer(sc.layers.backdrop, 1, g.backdrop)}
      {layout !== "fullbleed" && layout !== "plot" && O.ring && (
        <svg style={{position: "absolute", inset: 0}} width={W} height={H}>
          <circle cx={cx + g.hero.x * u} cy={cy + g.hero.y * u} r={R} fill="none" stroke={orn} strokeWidth={2} strokeDasharray={2 * Math.PI * R}
            strokeDashoffset={2 * Math.PI * R * (1 - interpolate(f, [6, 30], [0, 1], clamp))} />
          {[0, 1].map((i) => {
            const a = f / 40 + i * Math.PI;
            return <circle key={i} cx={cx + g.hero.x * u + R * Math.cos(a)} cy={cy + g.hero.y * u + R * Math.sin(a)} r={(i ? 9 : 14) * u} fill={orn} opacity={enter(3)} />;
          })}
        </svg>
      )}
      {sc.canvas && (
        <ProceduralCanvas
          kit={sc.canvas.kit}
          id={sc.id}
          bpm={sc.canvas.bpm ?? 120}
          transparent={sc.canvas.transparent ?? true}
          style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
        />
      )}
      {sc.bang && (
        <BangMotionOverlay
          src={sc.bang.video}
          transparent={sc.bang.transparent ?? true}
          blendMode={sc.bang.blendMode ?? "normal"}
        />
      )}
      {layout === "plot" ? (
        hasPlotVideo
          ? plotVideoLayer(sc.layers.plot, 2, g.hero, Boolean(sc.plot?.card ?? true))
          : layer(sc.layers.hero, 2, g.hero)
      ) : (
        <>
          {(!hasPlotVideo || hasSeparateHero) && layer(sc.layers.hero, 2, g.hero)}
          {hasPlotVideo && plotVideoLayer(
            sc.layers.plot,
            hasSeparateHero ? 3 : 2,
            hasSeparateHero ? {...g.hero, y: g.hero.y + 180, w: g.hero.w * 0.85} : g.hero,
            false,
          )}
        </>
      )}
      {layout !== "fullbleed" && props.map((k, i) => layer(sc.layers[k], 3 + i, g.props[i % g.props.length]))}
      {O.sparkles && layout !== "plot" && [[0.14, 0.27, 18], [0.82, 0.36, 14], [0.19, 0.72, 12], [0.79, 0.66, 20], [0.52, 0.22, 10]].map(([x, y, s], i) =>
        <Sparkle key={i} x={x * W} y={y * H} s={s * u} phase={i * 1.7} color={orn} />)}

      {sc.kicker && K && (
        <div style={{...textBox, top: kTop, display: "flex", justifyContent: textLeft ? "flex-start" : "center", alignItems: "center",
          gap: 22 * u, opacity: enter(0), fontFamily: `'${K.font}', serif`, fontSize: sz(K.size), letterSpacing: K.tracking, color: col(P, K.color)}}>
          {!textLeft && <span style={{width: 70 * u * enter(1), height: 1.5, background: col(P, "rule", orn)}} />}{sc.kicker}
          <span style={{width: 70 * u * enter(1), height: 1.5, background: col(P, "rule", orn)}} />
        </div>
      )}
      <div style={{...textBox, top: headTop, fontFamily: `'${Hd.font}', serif`, fontWeight: Hd.weight, fontSize: sz(Hd.size),
        letterSpacing: Hd.tracking, lineHeight: 1.15}}>
        {words.map((w, i) => {
          const at = M.headline === "line" ? 0 : (i * sc.frames * 0.6) / words.length;
          const t = interpolate(f, [at, at + 6], [0, 1], clamp);
          const acc = accent.has(w.toUpperCase().replace(/[^A-Z0-9]/g, ""));
          const hlProgress = interpolate(f, [at + 2, at + 10], [0, 100], clamp);
          const hlColor = col(P, "rule", col(P, "green", col(P, "accent", "#F2B705")));
          return (
            <span key={i} style={{position: "relative", display: "inline-block", opacity: t, transform: `translateY(${(1 - t) * 14 * u}px)`}}>
              {acc && (
                <span
                  style={{
                    position: "absolute",
                    left: -4 * u,
                    right: -4 * u,
                    bottom: "10%",
                    height: "46%",
                    background: hlColor,
                    opacity: 0.42,
                    borderRadius: 4 * u,
                    zIndex: 0,
                    clipPath: `inset(0 ${100 - hlProgress}% 0 0)`,
                    transform: "rotate(-1deg)",
                  }}
                />
              )}
              <span style={{position: "relative", zIndex: 1, fontStyle: acc && Hd.accentStyle === "italic" ? "italic" : "normal",
                color: col(P, acc ? Hd.accentColor : Hd.restColor)}}>
                {Hd.case === "upper" ? w.toUpperCase() : w}
              </span>
              &nbsp;
            </span>
          );
        })}
      </div>
      <div style={{...textBox, top: capTop, display: "flex", justifyContent: textLeft ? "flex-start" : "center", opacity: enter(2)}}>
        {(() => {
          const capBg = C.background && C.background !== "none" ? col(P, C.background) : "transparent";
          const capFg = capBg !== "transparent" ? contrastInk(col(P, C.color), capBg) : col(P, C.color);
          return (
            <span style={{background: capBg, color: capFg,
              fontFamily: `'${C.font}', sans-serif`, fontWeight: C.weight, fontStyle: C.style ?? "normal", fontSize: sz(C.size),
              padding: `${10 * u}px ${22 * u}px`, borderRadius: 10 * u, maxWidth: textLeft ? "100%" : Math.min(820 * u, safeW)}}>{sc.caption}</span>
          );
        })()}
      </div>
    </AbsoluteFill>
  );
};

// Load the Google Fonts stylesheet, then hold rendering until the faces are ready, so stills never use fallbacks.
const fontsUrl = (fonts: string[]) =>
  `https://fonts.googleapis.com/css2?${fonts.map((f) => "family=" + f.replace(/ /g, "+")).join("&")}&display=block`;
const useFonts = (fonts: string[]) => {
  const [handle] = React.useState(() => delayRender("web fonts"));
  React.useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet"; link.href = fontsUrl(fonts);
    const done = () => {
      const fams = fonts.map((f) => f.split(":")[0]);
      Promise.all(fams.flatMap((fam) => ["400", "700", "italic 400"].map((w) => document.fonts.load(`${w} 40px '${fam}'`).catch(() => null))))
        .then(() => document.fonts.ready).then(() => continueRender(handle));
    };
    link.onload = done; link.onerror = () => continueRender(handle);
    document.head.appendChild(link);
  }, [fonts, handle]);
};

export const StyleMotion: React.FC<StyleMotionProps> = ({style, scenes, audio}) => {
  const fade = style.motion?.fade ?? 8;
  const P = style.palette, B = style.background ?? {type: "radial"};
  const bg = B.type === "solid" ? col(P, B.from ?? "paper")
    : `radial-gradient(ellipse at 50% 45%, ${col(P, B.from ?? "paper")}, ${col(P, B.to ?? "paperShade", col(P, "paper"))})`;
  const fonts = style.type.fonts ?? [`${style.type.headline.font}:wght@400;700`, `${style.type.caption.font}:wght@500`];
  const fontKey = React.useMemo(() => fonts, [fonts.join("|")]);
  useFonts(fontKey);
  return (
    <AbsoluteFill style={{background: bg}}>
      {scenes.map((sc) => (
        <Sequence key={sc.id} from={sc.from} durationInFrames={sc.frames + fade}>
          <SceneView sc={{...sc, frames: sc.frames + fade}} style={style} fade={fade} />
        </Sequence>
      ))}
      {audio && <Audio src={staticFile(audio)} />}
    </AbsoluteFill>
  );
};

const demo = {style: {canvas: {width: 1080, height: 1920, fps: 30}, palette: {}, type: {headline: {}, caption: {}}}, scenes: [], audio: null} as unknown as StyleMotionProps;

export const StyleMotionRoot: React.FC = () => (
  <Composition id="StyleMotion" component={StyleMotion} width={1080} height={1920} fps={30} durationInFrames={30} defaultProps={demo}
    calculateMetadata={({props}) => {
      const last = props.scenes[props.scenes.length - 1];
      const fade = props.style.motion?.fade ?? 8;
      return {durationInFrames: last ? last.from + last.frames + fade : 30, fps: props.style.canvas.fps,
        width: props.style.canvas.width, height: props.style.canvas.height};
    }} />
);
